'use client'

import * as React from 'react'
import { Tabs as TabsPrimitive } from 'radix-ui'
import { cva } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { useSlidingIndicator } from '@/registry/satin/ui/sliding-indicator'
import { trackPointerModality } from '@/registry/satin/ui/pointer-modality'

// Rings after a mouse press: see pointer-modality.tsx.
trackPointerModality()

/**
 * Tabs, 1:1 with the uiKit `Tabs` (3635:18677) and `tabs/item` (3635:18591) sets.
 *
 * Underline: tabs 32px apart on a border/default rule; md is 36px high with a 14px label,
 * sm 32px with 13px. The selected tab has a 2px action/primary indicator sitting on the rule;
 * hover shows it in border/strong. Focus draws a 1.5px border/focus ring around the label.
 *
 * Pill: tabs 4px apart, radius-full; md 32px high with 12px sides, sm 28px with 10px. Hover
 * fills bg/muted, selected bg/selected, focus a 1px border/focus ring.
 *
 * The selected tab's indicator (the underline's 2px bar, the pill's bg/selected) is one element
 * that slides from tab to tab under the labels, as in the Segmented control and Pagination
 * (sliding-indicator.tsx): 300 ms, the leading edge first.
 *
 * Labels are text/muted, text/default on hover, focus and selected; disabled is 50%. Optional
 * 16px leading icon, 6px from the label. Built on the Radix Tabs (arrow keys move between tabs).
 * States answer to `data-force="hover" | "focus"` for state sheets.
 *
 * Other props, `ref` included, go to the Radix Tabs root (`aria-label` names the tab list instead).
 */
export type TabItem =
  | string
  | {
      value: string
      label: React.ReactNode
      /** 16px leading icon. */
      icon?: React.ReactNode
      disabled?: boolean
    }

export interface TabsProps
  extends Omit<
    React.ComponentProps<typeof TabsPrimitive.Root>,
    'value' | 'defaultValue' | 'onValueChange' | 'children' | 'asChild' | 'aria-label'
  > {
  items: TabItem[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  variant?: 'underline' | 'pill'
  size?: 'md' | 'sm'
  /** Disable every tab. */
  disabled?: boolean
  /** Accessible name for the tab list. */
  'aria-label'?: string
  /** `TabsContent` panels, one per item value. */
  children?: React.ReactNode
  className?: string
}

const list = cva('sa:relative sa:flex', {
  variants: {
    variant: {
      // The rule is an inset shadow, so the 2px indicator can sit on top of it (as in Figma).
      underline: 'sa:items-end sa:gap-8 sa:[box-shadow:inset_0_calc(var(--sa-border-width-default)*-1)_0_var(--sa-border-default)]',
      pill: 'sa:items-center sa:gap-1',
    },
  },
})

const trigger = cva(
  [
    'sa:group/tab sa:relative sa:flex sa:shrink-0 sa:items-center sa:font-medium sa:whitespace-nowrap sa:text-text-muted sa:select-none',
    'sa:transition-[color,background-color,box-shadow] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
    'sa:focus-visible:outline-none sa:disabled:pointer-events-none sa:disabled:opacity-50',
    'sa:satin-hover:text-text-default sa:satin-focus:text-text-default sa:data-[state=active]:text-text-default',
    'sa:[&_svg]:pointer-events-none sa:[&_svg]:size-4 sa:[&_svg]:shrink-0 sa:[&_svg]:[stroke-width:1.875]',
  ],
  {
    variants: {
      variant: {
        underline: '',
        pill: [
          'sa:rounded-pill',
          'sa:data-[state=inactive]:satin-hover:bg-bg-muted',
          'sa:satin-focus:[box-shadow:0_0_0_1px_var(--sa-border-focus)]',
        ],
      },
      size: {
        md: 'sa:text-base',
        sm: 'sa:text-sm',
      },
    },
    compoundVariants: [
      { variant: 'sa:underline', size: 'md', className: 'sa:h-control-height-xl' },
      { variant: 'sa:underline', size: 'sm', className: 'sa:h-control-height-lg' },
      { variant: 'pill', size: 'md', className: 'sa:h-control-height-lg sa:px-3' },
      { variant: 'pill', size: 'sm', className: 'sa:h-control-height sa:px-2.5' },
    ],
  },
)

function normalize(item: TabItem) {
  return typeof item === 'string' ? { value: item, label: item as React.ReactNode } : item
}

export function Tabs({
  items,
  value,
  defaultValue,
  onValueChange,
  variant = 'underline',
  size = 'md',
  disabled = false,
  children,
  className,
  'aria-label': ariaLabel,
  ...props
}: TabsProps) {
  const tabs = items.map(normalize)
  const listRef = React.useRef<HTMLDivElement>(null)
  // Uncontrolled tabs: follow the selection here too, so the indicator knows when to move.
  const [current, setCurrent] = React.useState(value ?? defaultValue ?? tabs[0]?.value)
  const selected = value ?? current
  const indicator = useSlidingIndicator(listRef, '[role="tab"][data-state="active"]', `${selected}|${variant}|${size}|${tabs.length}`)

  return (
    <TabsPrimitive.Root
      {...props}
      data-slot="tabs"
      value={value}
      defaultValue={defaultValue ?? (value === undefined ? tabs[0]?.value : undefined)}
      onValueChange={(v) => {
        setCurrent(v)
        onValueChange?.(v)
      }}
      className={cn('sa:flex sa:flex-col', className)}
    >
      <TabsPrimitive.List ref={listRef} aria-label={ariaLabel} className={list({ variant })}>
        <span
          ref={indicator.ref}
          aria-hidden
          className={cn(
            'sa:pointer-events-none sa:absolute sa:left-0 sa:opacity-0',
            variant === 'sa:underline' ? 'sa:bottom-0 sa:z-10 sa:h-0.5 sa:rounded-full sa:bg-action-primary-bg' : 'sa:top-1/2 sa:z-0 sa:-translate-y-1/2 sa:rounded-pill sa:bg-bg-selected',
            variant === 'pill' && (size === 'md' ? 'sa:h-control-height-lg' : 'sa:h-control-height'),
          )}
        />
        {tabs.map((tab) => (
          <TabsPrimitive.Trigger
            key={tab.value}
            value={tab.value}
            disabled={disabled || tab.disabled}
            // Without TabsContent there is no panel to point at.
            {...(children == null && { 'aria-controls': undefined })}
            className={cn(
              trigger({ variant, size }),
              variant === 'pill' && 'sa:z-10',
              // Before the indicator is placed (server render), the selected tab paints its own.
              !indicator.ready && variant === 'pill' && 'sa:data-[state=active]:bg-bg-selected',
            )}
          >
            <span
              className={cn(
                'sa:flex sa:items-center sa:gap-1.5 sa:rounded-sm',
                variant === 'sa:underline' &&
                  'sa:group-focus-visible/tab:[box-shadow:inset_0_0_0_1.5px_var(--sa-border-focus)] sa:group-data-[force=focus]/tab:[box-shadow:inset_0_0_0_1.5px_var(--sa-border-focus)]',
              )}
            >
              {tab.icon}
              {tab.label}
            </span>
            {variant === 'underline' && (
              <span
                aria-hidden
                className={cn(
                  'sa:absolute sa:inset-x-0 sa:bottom-0 sa:h-0.5 sa:rounded-full sa:bg-transparent',
                  'sa:transition-colors sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
                  'sa:group-data-[state=inactive]/tab:group-hover/tab:bg-border-strong sa:group-data-[state=inactive]/tab:group-data-[force=hover]/tab:bg-border-strong',
                  !indicator.ready && 'sa:group-data-[state=active]/tab:bg-action-primary-bg',
                )}
              />
            )}
          </TabsPrimitive.Trigger>
        ))}
      </TabsPrimitive.List>
      {children}
    </TabsPrimitive.Root>
  )
}

/** The panel for one tab value. */
export function TabsContent({ className, ...props }: React.ComponentProps<typeof TabsPrimitive.Content>) {
  return <TabsPrimitive.Content data-slot="tabs-content" className={cn('sa:rounded-md sa:focus-visible:shadow-border-focus sa:focus-visible:outline-none', className)} {...props} />
}
